//! Checks the statistics routines against scikit-learn 1.9.0 (and numpy for the
//! median/MAD rule). The expected numbers were generated by the script in
//! `tests/fixtures/sklearn/generate.py`; rerun it if the dataset changes.
//!
//! The datasets come from integer formulas, so they are reproducible without a
//! data file.

use tpt_bio_core::stats::Matrix;
use tpt_bio_core::stats::cluster::kmeans;
use tpt_bio_core::stats::normalize::{Method, normalize_columns};
use tpt_bio_core::stats::pca::Pca;

const TOL: f64 = 1e-9;

fn close(actual: f64, expected: f64) -> bool {
    (actual - expected).abs() <= TOL * expected.abs().max(1.0)
}

/// 12 samples x 3 features: `((i*37 + j*11) % 17) + 0.5*j`.
fn spread_data() -> Matrix {
    let rows: Vec<Vec<f64>> = (0..12)
        .map(|i| (0..3).map(|j| f64::from((i * 37 + j * 11) % 17) + 0.5 * j as f64).collect())
        .collect();
    Matrix::from_rows(&rows).unwrap()
}

/// 12 samples in three blobs of four rows, centred at 0, 10 and 20.
fn blob_data() -> Matrix {
    let rows: Vec<Vec<f64>> = (0..12)
        .map(|i| {
            (0..3).map(|j| 10.0 * f64::from(i / 4) + f64::from((i * 7 + j * 3) % 5) * 0.1).collect()
        })
        .collect();
    Matrix::from_rows(&rows).unwrap()
}

#[test]
fn zscore_matches_scikit_learn_standard_scaler() {
    let z = normalize_columns(&spread_data(), Method::ZScore).unwrap();
    let first = [-1.554_057_379_771_622_6, 0.699_283_601_275_065_8, -0.489_498_520_892_546_1];
    let last = [1.554_057_379_771_622_6, 0.489_498_520_892_546_1, -0.699_283_601_275_065_8];
    for j in 0..3 {
        assert!(close(z.get(0, j), first[j]), "row 0 col {j}: {}", z.get(0, j));
        assert!(close(z.get(11, j), last[j]), "row 11 col {j}: {}", z.get(11, j));
    }
}

#[test]
fn robust_matches_median_and_mad_reference() {
    let z = normalize_columns(&spread_data(), Method::Robust).unwrap();
    let first = [-1.199_094_683_513_947, 0.505_868_069_607_447_4, -0.337_245_379_738_297_6];
    let last = [1.199_094_683_513_947, 0.337_245_379_738_297_6, -0.505_868_069_607_447_4];
    for j in 0..3 {
        assert!(close(z.get(0, j), first[j]), "row 0 col {j}: {}", z.get(0, j));
        assert!(close(z.get(11, j), last[j]), "row 11 col {j}: {}", z.get(11, j));
    }
}

#[test]
fn pca_matches_scikit_learn() {
    let pca = Pca::fit(&spread_data(), 2).unwrap();

    let mean = [8.0, 8.166_666_666_666_666, 8.333_333_333_333_334];
    for (a, e) in pca.mean().iter().zip(mean) {
        assert!(close(*a, e), "mean {a} vs {e}");
    }

    // Explained variance uses the n-1 denominator, as scikit-learn does.
    let variance = [35.345_745_839_826_684, 35.030_303_030_303_03];
    for (a, e) in pca.explained_variance().iter().zip(variance) {
        assert!(close(*a, e), "variance {a} vs {e}");
    }
    let ratio = [0.450_351_201_820_185_56, 0.446_332_046_332_046_4];
    for (a, e) in pca.explained_variance_ratio().iter().zip(ratio) {
        assert!(close(*a, e), "ratio {a} vs {e}");
    }

    // Axes are unique up to sign. The sign of the second axis is a tie in our rule,
    // so compare absolute values.
    let axis1: [f64; 3] = [0.873_887_448_753_925, -0.343_744_619_529_06, -0.343_744_619_529_06];
    let axis2: [f64; 3] = [0.0, -0.707_106_781_186_747_4, 0.707_106_781_186_747_7];
    let c = pca.components();
    for j in 0..3 {
        assert!(close(c.get(0, j).abs(), axis1[j].abs()), "axis 1 col {j}");
        assert!(close(c.get(1, j).abs(), axis2[j].abs()), "axis 2 col {j}");
    }

    let scores = pca.transform(&spread_data()).unwrap();
    assert!(close(scores.get(0, 0).abs(), 7.334_844_209_560_56), "score {}", scores.get(0, 0));
    assert!(close(scores.get(0, 1).abs(), 4.006_938_426_723_771), "score {}", scores.get(0, 1));
}

#[test]
fn kmeans_recovers_blobs_with_scikit_learn_inertia() {
    let km = kmeans(&blob_data(), 3, 0, 100).unwrap();

    // Same partition as scikit-learn (ARI 1.0): rows 0-3, 4-7 and 8-11 each share a label,
    // and the three labels differ.
    let truth = |i: usize| i / 4;
    for i in 0..12 {
        for j in 0..12 {
            assert_eq!(
                km.labels[i] == km.labels[j],
                truth(i) == truth(j),
                "rows {i} and {j} disagree with the blob partition"
            );
        }
    }

    // scikit-learn reports inertia 0.6625 for this optimum.
    assert!(close(km.inertia, 0.6625), "inertia {}", km.inertia);
}
